	var events: Array = InputMap.action_get_events(action)
	if events.is_empty():
		return null
	return events[0]

func save_to_file(path: String = "user://input_map.cfg") -> void:
	var cfg := ConfigFile.new()
	for action in InputMap.get_actions():
		var events: Array = InputMap.action_get_events(action)
		var serialized: Array = []
		for ev in events:
